"""Constant-time counting function for the anti-Fibonacci sequence.

C(N) = #{k : a(k) <= N}.  Because a(k) <= N is equivalent to (2k-1)^2 <= 8N - 7,
the admissible indices form the initial segment [0, T(N)) with
T(N) = floor((floor(sqrt(8N-7)) + 1) / 2) + 1, so C(N) = T(N).
"""

from __future__ import annotations

from math import isqrt, sqrt


def anti_fib(n: int) -> int:
    return n * (n - 1) // 2 + 1


def count_closed(N: int) -> int:
    """C(N) in O(log N) bit operations (one integer square root)."""
    if N < 1:
        return 0
    return (isqrt(8 * N - 7) + 1) // 2 + 1


def count_naive(N: int) -> int:
    """Reference implementation: generate terms until they exceed N."""
    c, k = 0, 0
    while anti_fib(k) <= N:
        c += 1
        k += 1
    return c


def verify(limit: int = 20000) -> bool:
    """Closed form matches the scan, and both proved integer bounds hold."""
    for N in range(1, limit + 1):
        c = count_closed(N)
        if c != count_naive(N):
            return False
        if not (2 * N + c <= c * c + 1 and c * c + 4 <= 2 * N + 3 * c):
            return False
        if not (sqrt(2 * N) <= c <= sqrt(2 * N) + 3):
            return False
    return True


def demo() -> None:
    print("  verification on 1 <= N <= 20000:", verify())
    print(f"  {'N':>14} {'C(N)':>10} {'sqrt(2N)':>16} {'C - sqrt(2N)':>14}")
    for e in range(1, 16):
        N = 10 ** e
        c = count_closed(N)
        print(f"  {N:>14d} {c:>10d} {sqrt(2*N):>16.4f} {c - sqrt(2*N):>14.4f}")
    print("  density C(N)/N -> 0 :",
          ", ".join(f"{count_closed(10**e)/10**e:.2e}" for e in (3, 6, 9, 12)))


if __name__ == "__main__":
    demo()

