algorithms.code:
"""Three-term arithmetic progressions in the anti-Fibonacci sequence.

a(a) + a(c) = 2 a(b)  <=>  (a + c - 1)^2 + (c - a)^2 = (2b - 1)^2.

So progressions are exactly Pythagorean triples with odd hypotenuse.  Running the
classical parametrisation x = u^2 - v^2, y = 2uv, z = u^2 + v^2 (scaled) therefore
enumerates every progression.
"""

from __future__ import annotations

from math import gcd


def anti_fib(n: int) -> int:
    return n * (n - 1) // 2 + 1


def triple_to_progression(x: int, y: int, z: int) -> tuple[int, int, int] | None:
    """Convert a Pythagorean triple with odd hypotenuse into indices a < b < c."""
    if z % 2 == 0 or x <= y or y < 1 or x * x + y * y != z * z:
        return None
    if (x - y) % 2 == 0:
        return None
    a = (x - y + 1) // 2
    b = (z + 1) // 2
    c = (x + y + 1) // 2
    return (a, b, c) if a < b < c else None


def progressions(u_max: int) -> list[tuple[int, int, int]]:
    """All progressions produced by primitive triples with generators u > v."""
    out: set[tuple[int, int, int]] = set()
    for u in range(2, u_max + 1):
        for v in range(1, u):
            if (u - v) % 2 == 0 or gcd(u, v) != 1:
                continue
            legs = sorted((u * u - v * v, 2 * u * v), reverse=True)
            hyp = u * u + v * v
            for k in range(1, 4):
                p = triple_to_progression(k * legs[0], k * legs[1], k * hyp)
                if p is not None:
                    out.add(p)
    return sorted(out)


def canonical_family(k: int) -> tuple[int, int, int]:
    """The family a(k^2) + a((k+1)^2) = 2 a(k^2 + k + 1) from (2k+1, 2k^2+2k, 2k^2+2k+1)."""
    return k * k, k * k + k + 1, (k + 1) ** 2


def pyramidal(k: int) -> int:
    return k * (k + 1) * (2 * k + 1) // 6


def demo() -> None:
    print("  progressions from primitive triples (u <= 6):")
    for (a, b, c) in progressions(6)[:12]:
        ok = anti_fib(a) + anti_fib(c) == 2 * anti_fib(b)
        print(f"    indices ({a:3d},{b:3d},{c:3d})  "
              f"{anti_fib(a):6d} + {anti_fib(c):6d} = 2 * {anti_fib(b):6d}   {ok}")
    print("  the canonical family and its square-pyramidal common difference:")
    for k in range(1, 8):
        a, b, c = canonical_family(k)
        d = anti_fib(b) - anti_fib(a)
        print(f"    k={k}: ({a:3d},{b:3d},{c:3d})  difference {d:6d} = 3 * {pyramidal(k)}"
              f"   {d == 3 * pyramidal(k)}")


if __name__ == "__main__":
    demo()

