algorithms.code:
"""Additive decompositions into anti-Fibonacci numbers.

Two summands:  m = a(i) + a(j)      <=>  8m - 14 is a sum of two squares.
Three summands: m = a(i)+a(j)+a(k)  <=>  8m - 21 is a sum of three squares.
Four summands:  possible exactly for m >= 4, via "every 8k+4 is a sum of four odd
squares" applied to 8(m-4) + 4.
"""

from __future__ import annotations

from math import isqrt


def anti_fib(n: int) -> int:
    return n * (n - 1) // 2 + 1


def is_sum_of_two_squares(n: int) -> bool:
    """Fermat's criterion: every prime = 3 (mod 4) occurs to an even power."""
    if n < 0:
        return False
    m, q = n, 2
    while q * q <= m:
        if m % q == 0:
            e = 0
            while m % q == 0:
                m //= q
                e += 1
            if q % 4 == 3 and e % 2:
                return False
        q += 1
    return m % 4 != 3


def sum_of_two(m: int) -> bool:
    """Is m a sum of two anti-Fibonacci numbers?"""
    return m >= 2 and is_sum_of_two_squares(8 * m - 14)


def blocked_mod_nine(m: int) -> bool:
    """The O(1) obstruction: m = 1 or 7 (mod 9) is never a sum of two terms."""
    return m % 9 in (1, 7)


def four_odd_squares(target: int) -> tuple[int, int, int, int] | None:
    """Represent target = 8k + 4 as a sum of four odd squares."""
    for x in range(1, isqrt(target) + 1, 2):
        rx = target - x * x
        for y in range(1, isqrt(rx) + 1, 2):
            ry = rx - y * y
            for z in range(1, isqrt(ry) + 1, 2):
                rz = ry - z * z
                w = isqrt(rz)
                if w * w == rz and w % 2 == 1:
                    return x, y, z, w
    return None


def four_summands(m: int) -> tuple[int, int, int, int] | None:
    """Indices (p,q,r,s) with a(p)+a(q)+a(r)+a(s) = m, defined exactly for m >= 4."""
    if m < 4:
        return None
    rep = four_odd_squares(8 * (m - 4) + 4)
    if rep is None:
        return None
    p, q, r, s = ((v + 1) // 2 for v in rep)
    return p, q, r, s


def demo() -> None:
    print("  four-summand decompositions (valid exactly for m >= 4):")
    for m in (4, 5, 6, 7, 19, 46, 100, 1000):
        idx = four_summands(m)
        tot = sum(anti_fib(i) for i in idx) if idx else None
        print(f"    m = {m:5d}  indices {idx}  sum {tot}  {tot == m}")
    print("  m < 4 has none:", [four_summands(m) for m in range(4)])
    print("  two summands: non-representable m < 60:",
          [m for m in range(2, 60) if not sum_of_two(m)])
    print("  every m = 1,7 (mod 9) is blocked (checked to 2000):",
          all(not sum_of_two(m) for m in range(2, 2000) if blocked_mod_nine(m)))
    n = sum(1 for m in range(2, 2000) if not sum_of_two(m))
    print(f"  observed density of non-representables below 2000: {n/1998:.3f} (>= 2/9)")


if __name__ == "__main__":
    demo()
